create extension if not exists "pgcrypto";
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, course text, institution text, semester text, preferences jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.subjects (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, code text, name text not null check (char_length(name) between 1 and 160), professor text, credits integer not null default 0 check (credits >= 0), workload integer not null default 0 check (workload >= 0), room text, color text, category text, total_classes integer not null default 0 check (total_classes >= 0), max_absences integer not null default 0 check (max_absences >= 0), current_grade numeric(4,2) check (current_grade between 0 and 10), syllabus jsonb not null default '[]'::jsonb, ai_insight text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id) on delete set null, title text not null check (char_length(title) between 1 and 300), description text not null default '', due_date timestamptz, priority text not null default 'media' check (priority in ('urgente','alta','media','baixa')), status text not null default 'pending' check (status in ('pending','in_progress','completed')), estimated_time text, is_ai_prioritized boolean not null default false, has_ai_badge boolean not null default false, ai_badge_text text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.subtasks (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, text text not null, completed boolean not null default false, position integer not null default 0);
create table public.assessments (id uuid primary key default gen_random_uuid(), subject_id uuid not null references public.subjects(id) on delete cascade, name text not null, weight numeric(5,4) not null check (weight between 0 and 1), grade numeric(4,2) check (grade between 0 and 10), assessment_date date, status text not null default 'pending' check (status in ('pending','upcoming','completed')));
create table public.attendance_records (id uuid primary key default gen_random_uuid(), subject_id uuid not null references public.subjects(id) on delete cascade, class_date date not null default current_date, status text not null check (status in ('present','absent')), unique(subject_id, class_date));
create table public.chat_conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null default 'Conversa acadêmica', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.chat_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.chat_conversations(id) on delete cascade, role text not null check (role in ('user','assistant','tool')), content text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.study_plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, description text, plan jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index tasks_user_due_idx on public.tasks(user_id, due_date); create index subjects_user_idx on public.subjects(user_id); create index conversations_user_idx on public.chat_conversations(user_id); create index plans_user_idx on public.study_plans(user_id);
create function public.set_owner() returns trigger language plpgsql security definer set search_path = public as $$ begin if new.user_id is null then new.user_id = auth.uid(); end if new.user_id <> auth.uid() then raise exception 'cannot write another user''s data'; end if; return new; end; $$;
create function public.create_profile() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id, full_name) values(new.id, coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.create_profile();
create trigger owner_subjects before insert on public.subjects for each row execute procedure public.set_owner(); create trigger owner_tasks before insert on public.tasks for each row execute procedure public.set_owner(); create trigger owner_conversations before insert on public.chat_conversations for each row execute procedure public.set_owner(); create trigger owner_plans before insert on public.study_plans for each row execute procedure public.set_owner();
alter table public.profiles enable row level security; alter table public.subjects enable row level security; alter table public.tasks enable row level security; alter table public.subtasks enable row level security; alter table public.assessments enable row level security; alter table public.attendance_records enable row level security; alter table public.chat_conversations enable row level security; alter table public.chat_messages enable row level security; alter table public.study_plans enable row level security;
create policy "own profile" on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
create policy "own subjects" on public.subjects for all using (user_id = auth.uid()) with check (user_id = auth.uid()); create policy "own tasks" on public.tasks for all using (user_id = auth.uid()) with check (user_id = auth.uid()); create policy "own conversations" on public.chat_conversations for all using (user_id = auth.uid()) with check (user_id = auth.uid()); create policy "own plans" on public.study_plans for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own subtasks" on public.subtasks for all using (exists(select 1 from public.tasks t where t.id = task_id and t.user_id = auth.uid())) with check (exists(select 1 from public.tasks t where t.id = task_id and t.user_id = auth.uid()));
create policy "own assessments" on public.assessments for all using (exists(select 1 from public.subjects s where s.id = subject_id and s.user_id = auth.uid())) with check (exists(select 1 from public.subjects s where s.id = subject_id and s.user_id = auth.uid()));
create policy "own attendance" on public.attendance_records for all using (exists(select 1 from public.subjects s where s.id = subject_id and s.user_id = auth.uid())) with check (exists(select 1 from public.subjects s where s.id = subject_id and s.user_id = auth.uid()));
create policy "own messages" on public.chat_messages for all using (exists(select 1 from public.chat_conversations c where c.id = conversation_id and c.user_id = auth.uid())) with check (exists(select 1 from public.chat_conversations c where c.id = conversation_id and c.user_id = auth.uid()));
